import sys

def precompute_lengths():
    lengths = [len("What are you doing at the end of the world? Are you busy? Will you save us?")]
    for i in range(1, 100000):
        length = len(f'What are you doing while sending "{lengths[-1]}"? Are you busy? Will you send "{lengths[-1]}"?')
        lengths.append(length)
        if length > 10**18:
            break
    return lengths

def find_character(n, k, lengths):
    if n == 0:
        s = "What are you doing at the end of the world? Are you busy? Will you save us?"
        if k <= len(s):
            return s[k-1]
        else:
            return '.'

    length = lengths[n]
    if k > length:
        return '.'

    prefix_length = len('What are you doing while sending "') + lengths[n-1] + len('"? Are you busy? Will you send "') + lengths[n-1] + len('"?')
    if k <= prefix_length:
        return find_character(n-1, k - len('What are you doing while sending "') - 1, lengths)

    suffix_length = len('? Are you busy? Will you send "') + lengths[n-1] + len('"?')
    if k <= prefix_length + suffix_length:
        return find_character(n-1, k - prefix_length - 1, lengths)

    return ' '

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    q = int(data[0])
    queries = []
    index = 1
    for _ in range(q):
        n = int(data[index])
        k = int(data[index + 1])
        queries.append((n, k))
        index += 2

    lengths = precompute_lengths()
    results = []
    for n, k in queries:
        results.append(find_character(n, k, lengths))

    print(''.join(results))

