        else:
            return '.'

    len_prev = len_fn(n - 1)
    if k <= len_prev + 1:
        return '"'
    elif k <= len_prev + 1 + len_prev:
        return find_char(n - 1, k - len_prev - 1)
    elif k <= len_prev + 1 + len_prev + 1:
        return '"'
    elif k <= len_prev + 1 + len_prev + 1 + len_prev:
        return find_char(n - 1, k - len_prev - 1 - len_prev - 1)
    elif k <= len_prev + 1 + len_prev + 1 + len_prev + 1:
        return '"'
    else:
        return '.'

def main():
