def find_char(n, k):
    if n == 0:
        s = "What are you doing at the end of the world? Are you busy? Will you save us?"
        if k <= len(s):
            return s[k-1]
        else:
            return '.'

    # Length of f_{n-1}
    len_prev = 69 + 2 * len(find_char(n-1, 1))

    if k <= 69:
        return find_char(n-1, k)
    elif k <= 69 + len_prev:
        return find_char(n-1, (k - 69) // 2 + 1)
    else:
        return find_char(n-1, (k - 69 - len_prev) // 2 + 1)

